node --input-type=module <<'EOF'
import assert from 'node:assert/strict'
for (const [path, code, tokens] of [
  ['/', 200, ['Products', 'Classic Sneakers', 'product-card', 'product-image']],
  ['/product/classic-sneakers', 200, ['Back to products', 'Classic Sneakers', 'product-hero', 'Timeless design meets everyday comfort.']],
  ['/product/not-a-product', 404, []],
]) {
  const response = await fetch(`http://localhost:3100${path}`)
  const html = await response.text()
  assert.equal(response.status, code, `${path} status`)
  for (const token of tokens) assert.ok(html.includes(token), `${path}: missing ${token}`)
  console.log(`${path}: HTTP ${response.status}; ${tokens.length} content checks passed`)
}
EOF
